"use client"

import * as React from "react"
import { highlight } from "sugar-high"

import { cn } from "@/lib/utils"
import { roll } from "@/lib/0db/roll"
import { Button } from "@/components/ui/button"

type SourceProps = Omit<React.ComponentProps<"figure">, "children"> & {
  code: string
  /** Shown in the frame row, e.g. a file name. */
  title?: React.ReactNode
  /** Hide the Copy action. */
  noCopy?: boolean
}

/** Code, set as type. Strings are yours, in italic; keywords are ink; nothing else takes colour. */
function Source({ code, title, noCopy = false, className, ...props }: SourceProps) {
  const html = React.useMemo(() => highlight(code.replace(/\n$/, "")), [code])
  return (
    <figure data-slot="source" className={cn("db-source", className)} {...props}>
      {title || !noCopy ? (
        <figcaption data-slot="source-meta" className="db-meta db-source-meta">
          <span>{title}</span>
          <hr />
          {noCopy ? null : <CopyButton text={code} />}
        </figcaption>
      ) : null}
      <pre className="db-source-code" tabIndex={0}>
        <code dangerouslySetInnerHTML={{ __html: html }} />
      </pre>
    </figure>
  )
}

/** Copy keeps its name through the flow: Copy, then Copied. */
function CopyButton({ text, className, ...props }: React.ComponentProps<typeof Button> & { text: string }) {
  const label = React.useRef<HTMLSpanElement>(null)
  const [copied, setCopied] = React.useState(false)
  const timer = React.useRef<ReturnType<typeof setTimeout>>(undefined)

  React.useEffect(() => () => clearTimeout(timer.current), [])

  const show = (next: boolean) => {
    if (label.current) roll(label.current, () => setCopied(next), "0.5em", next ? 1 : -1)
    else setCopied(next)
  }

  return (
    <Button
      variant="bracket"
      data-slot="source-copy"
      className={cn("db-source-copy", className)}
      onClick={async () => {
        try {
          await navigator.clipboard.writeText(text)
        } catch {
          return // the browser refused; the label stays "Copy", which is true
        }
        show(true)
        clearTimeout(timer.current)
        timer.current = setTimeout(() => show(false), 1800)
      }}
      {...props}
    >
      <span ref={label} aria-live="polite">
        {copied ? "Copied" : "Copy"}
      </span>
    </Button>
  )
}

export { Source, CopyButton, type SourceProps }

@layer components {
  /* ── db-source ── code, set as type: a frame row (the name, a hairline, Copy)
     over the lines. What someone wrote (strings, JSX text) is in the expression,
     italic; keywords are ink; signs and comments are pencil. No second colour. */
  .db-source { margin: 0; min-width: 0; }
  .db-source-meta { margin-bottom: var(--db-space-4); }
  .db-source-meta > .db-btn { font-size: var(--db-pp); }
  .db-source-code {
    margin: 0; overflow-x: auto; tab-size: 2;
    font-family: var(--db-voice); font-stretch: 88%; font-size: 0.9375rem; line-height: 1.7; letter-spacing: 0.005em;
    font-variant-numeric: tabular-nums lining-nums; color: var(--db-graphite); white-space: pre;
    --sh-keyword: var(--db-ink); --sh-entity: var(--db-ink); --sh-class: var(--db-ink);
    --sh-identifier: var(--db-graphite); --sh-property: var(--db-graphite);
    --sh-string: var(--db-ink); --sh-jsxliterals: var(--db-ink);
    --sh-sign: var(--db-pencil); --sh-comment: var(--db-pencil); --sh-space: inherit;
  }
  .db-source-code > code { font: inherit; }
  .db-source-code .sh__token--keyword { font-weight: 500; }
  .db-source-code :is(.sh__token--string, .sh__token--jsxliterals) {
    font-family: var(--db-expression); font-style: italic; font-stretch: 100%;
    font-size: calc(var(--db-expression-scale) * 1em); line-height: 1;
  }
  .db-source-copy > span { display: inline-block; }
}
